import{_ as t,o,c as a,ag as c}from"./chunks/framework.D5hoimZQ.js";const _=JSON.parse('{"title":"科学日报 · 2026-09-16（地球科学 / 生命起源）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/earth-science/science-daily-2026-09-16.md","filePath":"topics/earth-science/science-daily-2026-09-16.md"}'),i={name:"topics/earth-science/science-daily-2026-09-16.md"};function s(r,e,n,l,d,u){return o(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="科学日报-·-2026-09-16-地球科学-生命起源" tabindex="-1">科学日报 · 2026-09-16（地球科学 / 生命起源） <a class="header-anchor" href="#科学日报-·-2026-09-16-地球科学-生命起源" aria-label="Permalink to &quot;科学日报 · 2026-09-16（地球科学 / 生命起源）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-16.md</code> — 第27期</p></blockquote><hr><h2 id="重思海底热泉与生命起源-对-碱性热泉假说-的修正-pnas" tabindex="-1">重思海底热泉与生命起源：对&quot;碱性热泉假说&quot;的修正（PNAS） <a class="header-anchor" href="#重思海底热泉与生命起源-对-碱性热泉假说-的修正-pnas" aria-label="Permalink to &quot;重思海底热泉与生命起源：对&quot;碱性热泉假说&quot;的修正（PNAS）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-16.md</code> ｜ DOI: 10.1073/pnas.2613108123</p></blockquote><ul><li>背景：&quot;碱性热泉假说&quot;（烷烃热泉/蛇纹石化系统）主张硫化物矿物膜上的<strong>强质子梯度</strong>驱动远古烟囱中原始细胞的化学渗透能量采集，是生命起源主流假说之一。</li><li>修正：结合近年对太古宙海底系统地质性质的新认识——远古蛇纹石化系统环流更浅、喷口更分散、活动更短，且 Lost City 流体须先冷却才呈超高碱；因此<strong>现代与古代蛇纹石化系统都不具备强的 pH 梯度</strong>。</li><li>结论：挑战&quot;把质子梯度当作热泉起源必要条件&quot;的主流推理，主张以更严格的化学约束重新评估热泉环境在生命起源中的角色。</li><li>洞察：这是对经典假说的<strong>负向修订</strong>——不是否认热泉参与，而是拆掉&quot;质子梯度必然存在&quot;这一支撑柱，提醒科学叙事要跟得上地质模型自身的更新；对地外宜居性与早期地球化学约束讨论同样重要。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/earth-science/index.md</code> ｜ 第27期 科学板块</p></blockquote>',8)])])}const q=t(i,[["render",s]]);export{_ as __pageData,q as default};
